"""扩展安装交接页，与后端一同打包。"""
CONNECT_HTML = '<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>连接可灵画布助手</title>\n<style>[hidden]{display:none!important}body{margin:60px auto;padding:24px;max-width:600px;font:16px/1.7 system-ui;background:#181b21;color:#eee}a,button{display:inline-block;padding:10px 18px;border-radius:8px;background:#eee;color:#182028;border:0;cursor:pointer}p{color:#bbc2cf}code{word-break:break-all}#status{color:#fff}</style>\n<h1>连接可灵画布助手</h1><p id="status" role="status">正在检测连接。未连接不代表尚未安装。</p>\n<section id="help"><p>首次使用，请在 Chrome 中安装扩展并确认权限。安装完成后，此页会自动继续原来的画布任务，请保留此页。</p>\n<a id="store" href="__STORE_URL__" target="_blank" rel="noopener noreferrer">前往 Chrome 商店安装</a><p id="unpublished" hidden>商店安装入口尚未配置，请联系拾影管理员获取正式发行版本。</p>\n<p>已经安装？请确认使用的是登录可灵的 Chrome 配置，并启用或更新“拾影 · 可灵画布助手”（最低版本 0.4.0）。</p>\n<p id="remote" hidden>此为远程 Web 站点。首次使用请打开插件，在“拾影地址”中填入 <code id="origin"></code>，点击“授权并连接”；仅向你信任的拾影站点授权。</p>\n<button id="retry">重新检测</button><button id="cancel">取消本次等待</button></section>\n<script>\nconst status=document.getElementById(\'status\'),store=document.getElementById(\'store\');\nif(!store.getAttribute(\'href\')){store.hidden=true;document.getElementById(\'unpublished\').hidden=false;}\nconst key=\'shiyin-kling-ticket\';let ticket=location.hash.slice(1) || sessionStorage.getItem(key) || \'\';\nif(/^[\\w-]{40,60}$/.test(ticket)){sessionStorage.setItem(key,ticket);history.replaceState(null,\'\',location.pathname);}else{ticket=\'\';status.textContent=\'缺少任务信息，请返回画布点击生成。\';}\nif(location.protocol===\'https:\'){document.getElementById(\'remote\').hidden=false;document.getElementById(\'origin\').textContent=location.origin;}\nlet stopped=false;\nasync function inspect(){if(!ticket || stopped)return;try{\n const response=await fetch(\'/api/kling-web/transport/status\',{headers:{Authorization:\'Bearer \'+ticket},cache:\'no-store\'});\n const data=await response.json();if(!response.ok)throw Error(data.detail || \'连接已过期\');\n if(data.status!==\'queued\'){status.textContent=data.message;stopped=true;sessionStorage.removeItem(key);document.getElementById(\'help\').hidden=true;}\n}catch(error){status.textContent=error.message;stopped=true;sessionStorage.removeItem(key);}}\ndocument.getElementById(\'retry\').onclick=()=>location.reload();\ndocument.getElementById(\'cancel\').onclick=async()=>{try{const response=await fetch(\'/api/kling-web/transport/cancel\',{method:\'POST\',headers:{Authorization:\'Bearer \'+ticket}});if(!response.ok)throw Error(\'任务已经接收或连接已过期，请返回画布查看\');stopped=true;sessionStorage.removeItem(key);ticket=\'\';document.getElementById(\'help\').hidden=true;status.textContent=\'已取消等待，未提交生成。\';}catch(error){status.textContent=error.message;}};\nsetInterval(inspect,2500);inspect();\n</script></html>'
